const attempt = { idempotencyKey: \"same-request\", environment: \"HOMOLOGATION\" as const, preparedPayload: \"fixture\", previouslyAttempted: false };
describe(\"fiscal provider coordination contract\", () => {
 it(\"queries after timeout without issuing another document\", async () => {
  const adapter: FiscalProviderAdapter = { code: \"TEST_ONLY\", environment: \"HOMOLOGATION\", submit: vi.fn().mockRejectedValue(new Error(\"timeout\")), queryStatus: vi.fn().mockResolvedValue({ status: \"PROCESSING\", remoteId: \"one\" }) };
